CREATE TABLE admin (Admin_ID INT AUTO_INCREMENT PRIMARY KEY, Username VARCHAR(30) NOT NULL UNIQUE, Password VARCHAR(255) NOT NULL, Full_Name VARCHAR(60) NOT NULL, Role ENUM('Admin','Teacher','Accountant','Librarian') NOT NULL, Status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active') ENGINE=InnoDB;
CREATE TABLE class (Class_ID INT AUTO_INCREMENT PRIMARY KEY, Class_Name VARCHAR(10) NOT NULL, Section CHAR(1) NOT NULL, UNIQUE(Class_Name,Section)) ENGINE=InnoDB;
CREATE TABLE teacher (Teacher_ID INT AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(60) NOT NULL, Qualification VARCHAR(60) NOT NULL, Contact CHAR(10) NOT NULL, Email VARCHAR(80) NOT NULL, Salary DECIMAL(10,2) NOT NULL) ENGINE=InnoDB;
CREATE TABLE subject (Subject_ID INT AUTO_INCREMENT PRIMARY KEY, Subject_Name VARCHAR(40) NOT NULL, Teacher_ID INT NOT NULL, FOREIGN KEY (Teacher_ID) REFERENCES teacher(Teacher_ID)) ENGINE=InnoDB;
CREATE TABLE student (Student_ID INT AUTO_INCREMENT PRIMARY KEY, Admission_No VARCHAR(15) NOT NULL UNIQUE, Name VARCHAR(60) NOT NULL, Gender ENUM('Male','Female','Other') NOT NULL, DOB DATE NOT NULL, Address VARCHAR(200) NOT NULL, Contact CHAR(10) NOT NULL, Parent_Name VARCHAR(60) NOT NULL, Parent_Contact CHAR(10) NOT NULL, Class_ID INT NOT NULL, FOREIGN KEY (Class_ID) REFERENCES class(Class_ID)) ENGINE=InnoDB;
CREATE TABLE attendance (Attendance_ID INT AUTO_INCREMENT PRIMARY KEY, Student_ID INT NOT NULL, Date DATE NOT NULL, Status ENUM('Present','Absent','Late') NOT NULL, UNIQUE(Student_ID,Date), FOREIGN KEY (Student_ID) REFERENCES student(Student_ID)) ENGINE=InnoDB;
CREATE TABLE examination (Exam_ID INT AUTO_INCREMENT PRIMARY KEY, Exam_Name VARCHAR(50) NOT NULL, Date DATE NOT NULL, Max_Marks INT NOT NULL DEFAULT 100) ENGINE=InnoDB;
CREATE TABLE result (Result_ID INT AUTO_INCREMENT PRIMARY KEY, Student_ID INT NOT NULL, Exam_ID INT NOT NULL, Subject_ID INT NOT NULL, Marks DECIMAL(5,1) NOT NULL, Grade VARCHAR(2) NOT NULL, UNIQUE(Student_ID,Exam_ID,Subject_ID), FOREIGN KEY (Student_ID) REFERENCES student(Student_ID), FOREIGN KEY (Exam_ID) REFERENCES examination(Exam_ID), FOREIGN KEY (Subject_ID) REFERENCES subject(Subject_ID)) ENGINE=InnoDB;
CREATE TABLE fees (Fee_ID INT AUTO_INCREMENT PRIMARY KEY, Student_ID INT NOT NULL, Fee_Type VARCHAR(40) NOT NULL, Amount DECIMAL(10,2) NOT NULL, Due_Date DATE NOT NULL, Payment_Date DATE NULL, Status ENUM('Paid','Pending') NOT NULL DEFAULT 'Pending', Receipt_No VARCHAR(20) NULL UNIQUE, Payment_Mode VARCHAR(10) NULL, FOREIGN KEY (Student_ID) REFERENCES student(Student_ID)) ENGINE=InnoDB;
CREATE TABLE book (Book_ID INT AUTO_INCREMENT PRIMARY KEY, Book_Name VARCHAR(100) NOT NULL, Author VARCHAR(60) NOT NULL, Status ENUM('Available','Issued') NOT NULL DEFAULT 'Available') ENGINE=InnoDB;
CREATE TABLE library (Issue_ID INT AUTO_INCREMENT PRIMARY KEY, Book_ID INT NOT NULL, Student_ID INT NOT NULL, Issue_Date DATE NOT NULL, Due_Date DATE NOT NULL, Return_Date DATE NULL, Fine_Amount DECIMAL(8,2) NOT NULL DEFAULT 0, FOREIGN KEY (Book_ID) REFERENCES book(Book_ID), FOREIGN KEY (Student_ID) REFERENCES student(Student_ID)) ENGINE=InnoDB;
